// Search across title + summary + address. Every typed word must appear somewhere.
function terms(){ return query.toLowerCase().split(/\s+/).filter(Boolean); }
function matches(b){
  const hay = (b.title+' '+b.desc+' '+b.url).toLowerCase();
  return terms().every(t => hay.includes(t));
}
function highlight(text){
  let out = escapeHtml(text);
  for (const t of terms()){
    if (!t) continue;
    const re = new RegExp('('+t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig');
    out = out.replace(re, '<mark>$1</mark>');
  }
  return out;
}

input.new_string:
// Search across title + summary + address. Every typed word must appear somewhere.
function terms(){ return query.toLowerCase().split(/\s+/).filter(Boolean); }
function currentLevel(){ return document.querySelector('input[name=matchmode]:checked').value; }

// Demo-tuned stemmer: folds common word forms to a shared root so "Rome"↔"Roman",
// "cook"↔"cooking", "recipe"↔"recipes". Simulated; the real app would use proper stemming.
function stem(w){
  w = w.toLowerCase();
  const roots = { rome:'rom', roman:'rom', romans:'rom' };
  if (roots[w]) return roots[w];
  w = w.replace(/(ings|ing|ed|es|s)$/,'');
  w = w.replace(/e$/,'');
  return w;
}
function wordHit(word, t, level){
  word = word.toLowerCase();
  if (word.includes(t)) return true;              // substring — covers exact typing
  if (level === 'exact') return false;
  if (level === 'forms') return stem(word) === stem(t);
  if (level === 'loose') return word.startsWith(t.slice(0,3)) || stem(word) === stem(t);
  return false;
}
function wordsOf(b){ return (b.title+' '+b.desc+' '+b.url).toLowerCase().split(/[^a-z0-9]+/).filter(Boolean); }
function matches(b){
  const level = currentLevel();
  const hay = (b.title+' '+b.desc+' '+b.url).toLowerCase();
  const words = wordsOf(b);
  return terms().every(t => hay.includes(t) || words.some(w => wordHit(w, t, level)));
}
function highlight(text){
  const level = currentLevel();
  const ts = terms();
  return escapeHtml(text).replace(/[A-Za-z0-9]+/g, w =>
    ts.some(t => wordHit(w, t, level)) ? '<mark>'+w+'</mark>' : w);
}

