function allLabels(){
  const set = [];
  bookmarks.forEach(b => (b.labels||[]).forEach(l => { if(!set.includes(l)) set.push(l); }));
  return set.sort();
}
function renderLabelBar(){
  const labels = allLabels();
  if (!labels.length){ document.getElementById('labelBar').innerHTML=''; return; }
  const chips = labels.map(l =>
    `<span class="chip ${l===labelFilter?'active':''}" onclick="toggleLabel('${escapeHtml(l)}')">${escapeHtml(l)}</span>`
  ).join('');
  document.getElementById('labelBar').innerHTML = '<span class="lead">Labels</span>' + chips;
}
window.toggleLabel = function(l){ labelFilter = (labelFilter===l ? null : l); render(); };

function render(){
  renderLabelBar();
  const q = query.trim();
  let shown = q ? bookmarks.filter(matches) : bookmarks.slice();
  if (labelFilter) shown = shown.filter(b => (b.labels||[]).includes(labelFilter));

  const filtering = q || labelFilter;
