function addMode(){ return document.querySelector('input[name=addmode]:checked').value; }

// Case-insensitive: reuse an existing label with matching spelling rather than making a near-duplicate.
function canonicalLabel(raw){
  const v = raw.trim(); if(!v) return '';
  const hit = allLabels().find(l => l.toLowerCase() === v.toLowerCase());
  return hit || v;
}
function hasLabel(b, l){ return (b.labels||[]).some(x => x.toLowerCase() === l.toLowerCase()); }

window.startEditLabels = function(id, ev){ if(ev) ev.stopPropagation(); editingLabelsId=id; renamingId=null; labelDraft=''; render(); };
window.closeLabels = function(){ editingLabelsId=null; labelDraft=''; render(); };
window.onLabelInput = function(v){ labelDraft=v; render(); };
window.addLabel = function(id, raw){
  const b = bookmarks.find(x=>x.id===id); if(!b) return;
  const label = canonicalLabel(raw); if(!label) return;
  b.labels = b.labels || [];
  if(!hasLabel(b, label)) b.labels.push(label);
  labelDraft=''; render();
};
window.labelKey = function(ev, id){
  if(ev.key==='Enter'){ ev.preventDefault(); if(labelDraft.trim()) addLabel(id, labelDraft); }
  else if(ev.key==='Escape'){ closeLabels(); }
};
window.removeLabel = function(ev, id, l){
  if(ev) ev.stopPropagation();
  const b = bookmarks.find(x=>x.id===id); if(!b) return;
  b.labels = (b.labels||[]).filter(x => x !== l);
  render();
};

function labelEditorMarkup(b){
  const mode = addMode();
  const cur = b.labels||[];
  const curBlock = cur.length
    ? '<div class="cur">'+cur.map(l=>`<span class="chip">${escapeHtml(l)}<span class="x" onclick="removeLabel(event,${b.id},'${escapeHtml(l)}')">×</span></span>`).join('')+'</div>'
    : '<div class="cur empty-cur">No labels on this link yet.</div>';

  const draft = labelDraft.trim();
  const notOnLink = l => !hasLabel(b, l);
  const matching = l => l.toLowerCase().includes(draft.toLowerCase());
  const exactExists = allLabels().some(l => l.toLowerCase() === draft.toLowerCase());

  let addArea = '';
  if (mode === 'A'){
    const sugg = allLabels().filter(notOnLink).filter(l => draft && matching(l))
      .map(l=>`<span class="addchip" onclick="addLabel(${b.id},'${escapeHtml(l)}')">${escapeHtml(l)}</span>`).join('');
    const create = (draft && !exactExists)
      ? `<span class="createchip" onclick="addLabel(${b.id},'${escapeHtml(draft)}')">＋ Create “${escapeHtml(draft)}”</span>` : '';
    addArea = `
      <div class="sec">Add a label</div>
      <input id="labelInput" placeholder="Type a label…" value="${escapeHtml(labelDraft)}"
             oninput="onLabelInput(this.value)" onkeydown="labelKey(event,${b.id})" onclick="event.stopPropagation()" autocomplete="off" />
      <div class="suggests">${sugg}${create}</div>
      ${draft && sugg ? '<div class="hintline">↑ You already have these — tap one to reuse it.</div>' : ''}`;
  } else if (mode === 'B'){
    const palette = allLabels().filter(notOnLink)
      .map(l=>`<span class="addchip" onclick="addLabel(${b.id},'${escapeHtml(l)}')">${escapeHtml(l)}</span>`).join('') || '<span class="empty-cur">No other labels yet.</span>';
    addArea = `
      <div class="sec">Tap one of your labels to add it</div>
      <div class="palette">${palette}</div>
      <div class="sec" style="margin-top:10px;">…or add a new one</div>
      <input id="labelInput" placeholder="New label…" value="${escapeHtml(labelDraft)}"
             oninput="onLabelInput(this.value)" onkeydown="labelKey(event,${b.id})" onclick="event.stopPropagation()" autocomplete="off" />`;
  } else {
    const palette = allLabels().filter(notOnLink).filter(l => !draft || matching(l))
      .map(l=>`<span class="addchip" onclick="addLabel(${b.id},'${escapeHtml(l)}')">${escapeHtml(l)}</span>`).join('');
    const create = (draft && !exactExists)
      ? `<span class="createchip" onclick="addLabel(${b.id},'${escapeHtml(draft)}')">＋ Create “${escapeHtml(draft)}”</span>` : '';
    addArea = `
      <div class="sec">Add a label — your labels are below; type to filter</div>
      <input id="labelInput" placeholder="Filter or create…" value="${escapeHtml(labelDraft)}"
             oninput="onLabelInput(this.value)" onkeydown="labelKey(event,${b.id})" onclick="event.stopPropagation()" autocomplete="off" />
      <div class="palette">${palette||'<span class="empty-cur">No matches.</span>'}${create}</div>`;
  }

  return `<div class="leditor" onclick="event.stopPropagation()">
    <div class="sec">Labels on this link</div>
    ${curBlock}
    ${addArea}
    <button class="done" onclick="closeLabels()">Done</button>
  </div>`;
}

