window.closeReader=function(){ document.getElementById('modal').innerHTML=''; };

let editConfirmDelete = false;
window.openEdit=function(id, ev){ if(ev) ev.stopPropagation(); editConfirmDelete=false; renderEdit(id); };
function renderEdit(id){
  const b=bookmarks.find(x=>x.id===id); if(!b) return;
  const confirmBlock = editConfirmDelete
    ? `<div class="confirm">
         <span>Delete this link for good? Your saved copy goes too.</span>
         <span class="spacer"></span>
         <button class="btn danger" onclick="confirmDelete(${b.id})">Yes, delete</button>
         <button class="btn" onclick="cancelDelete(${b.id})">Keep it</button>
       </div>` : '';
  document.getElementById('modal').innerHTML =
    `<div class="overlay" onclick="if(event.target===this) closeReader()">
      <div class="reader">
        <h2>Edit link</h2>
        <label class="f">Title</label>
        <input class="field" id="eTitle" value="${escapeHtml(b.title)}" />
        <label class="f">Your note (searchable)</label>
        <textarea class="field" id="eNote" placeholder="Jot anything — why you saved it, what to remember…">${escapeHtml(b.note||'')}</textarea>
        <label class="f">Summary (auto-filled — edit if it's off)</label>
        <textarea class="field" id="eDesc">${escapeHtml(b.desc||'')}</textarea>
        <label class="f">Address</label>
        <input class="field" id="eUrl" value="${escapeHtml(b.url)}" />
        <div class="rowbtns">
          <button class="btn primary" onclick="saveEdit(${b.id})">Save</button>
          <button class="btn" onclick="closeReader()">Cancel</button>
          <span class="spacer"></span>
          <button class="btn danger" onclick="askDelete(${b.id})">Delete link</button>
        </div>
        ${confirmBlock}
      </div>
    </div>`;
}
window.saveEdit=function(id){
  const b=bookmarks.find(x=>x.id===id); if(!b) return;
  const t=document.getElementById('eTitle').value.trim();
  const u=document.getElementById('eUrl').value.trim();
  if(t) b.title=t;
  b.note=document.getElementById('eNote').value.trim();
  b.desc=document.getElementById('eDesc').value.trim();
  if(u) b.url = /^https?:\/\//i.test(u) ? u : 'https://'+u;
  closeReader(); render();
};
window.askDelete=function(id){ editConfirmDelete=true; renderEdit(id); };
window.cancelDelete=function(id){ editConfirmDelete=false; renderEdit(id); };
window.confirmDelete=function(id){
  const i=bookmarks.findIndex(x=>x.id===id);
  if(i>=0){ const t=bookmarks[i].title; bookmarks.splice(i,1); closeReader(); showBanner('Deleted “'+t+'”.'); render(); }
};

