window.closeReader=function(){ document.getElementById('modal').innerHTML=''; };

// ---- Import / Export ----
const SAMPLE_IMPORT = [
  'Ancient Rome - Wikipedia | https://en.wikipedia.org/wiki/Ancient_Rome | History',
  'Best Neapolitan Pizza Dough | https://cooking.example.com/pizza-dough | Recipes/Italian',
  'Tax Filing Guide 2026 | https://gov.example.com/tax-guide | Work/Reference',
  'Kyoto 5-Day Itinerary | https://travel.example.com/kyoto | Travel/Japan',
  'Rust Ownership Explained | https://devblog.example.com/rust-ownership | Coding',
  'Sourdough Starter Basics | https://cooking.example.com/sourdough | Recipes/Bread',
  'Team Offsite Notes | https://portal.example.com/members/offsite | Work/Reference'
].join('\n');

function folderToLabels(folder){ return (folder||'').split('/').map(s=>s.trim().toLowerCase()).filter(Boolean); }

window.openImport=function(){
  document.getElementById('modal').innerHTML =
    `<div class="overlay" onclick="if(event.target===this) closeReader()">
      <div class="reader">
        <h2>Bring in your bookmarks</h2>
        <div class="arch">Paste your browser's exported bookmarks (or load a sample to see how it works).
        We'll <b>skip any you already have</b>, and turn each bookmark's <b>folder into labels</b> so your old
        filing isn't lost — just freed from single-folder prison.</div>
        <label class="f">Bookmarks — one per line: <code>Title | https://… | Folder/Subfolder</code></label>
        <textarea class="field" id="importText" style="min-height:120px;" placeholder="Ancient Rome | https://en.wikipedia.org/wiki/Ancient_Rome | History"></textarea>
        <div class="rowbtns">
          <button class="btn" onclick="loadSampleImport()">Load a sample browser export</button>
        </div>
        <div class="rowbtns">
          <button class="btn primary" onclick="doImport()">Import</button>
          <button class="btn" onclick="closeReader()">Cancel</button>
        </div>
      </div>
    </div>`;
};
window.loadSampleImport=function(){ const t=document.getElementById('importText'); if(t) t.value=SAMPLE_IMPORT; };
window.doImport=function(){
  const raw=(document.getElementById('importText')||{}).value||'';
  const lines=raw.split('\n').map(s=>s.trim()).filter(Boolean);
  let added=0, skippedDup=0, skippedBad=0;
  lines.forEach(line=>{
    const parts=line.split('|').map(s=>s.trim());
    const title=parts[0]||''; let url=parts[1]||''; const folder=parts[2]||'';
    if(url && !/^https?:\/\//i.test(url)) url='https://'+url;
    if(!isUrlLike(url)){ skippedBad++; return; }
    if(bookmarks.find(b=>keyFor(b.url)===keyFor(url))){ skippedDup++; return; }
    bookmarks.unshift({ id:nextId++, url, title:title||hostOf(url), desc:'', labels:folderToLabels(folder), imported:true });
    added++;
  });
  closeReader();
  let msg='Imported '+added+' link'+(added===1?'':'s');
  if(skippedDup) msg+=', skipped '+skippedDup+' you already had';
  if(skippedBad) msg+=', ignored '+skippedBad+" that weren't links";
  msg+='. Folders became labels.';
  showBanner(msg);
  render();
};

window.openExport=function(){
  const text = bookmarks.map(b=>{
    const labels=(b.labels||[]).join(', ');
    return b.title+' | '+b.url+(labels?(' | '+labels):'');
  }).join('\n');
  document.getElementById('modal').innerHTML =
    `<div class="overlay" onclick="if(event.target===this) closeReader()">
      <div class="reader">
        <h2>Export your links</h2>
        <div class="arch">Your links, yours to take anywhere — nothing locked in. Copy this, or download it as a file.</div>
        <textarea class="field" style="min-height:200px;" readonly>${escapeHtml(text)}</textarea>
        <div class="rowbtns">
          <button class="btn primary" onclick="downloadExport()">Download file</button>
          <button class="btn" onclick="closeReader()">Done</button>
        </div>
      </div>
    </div>`;
};
window.downloadExport=function(){
  const text = bookmarks.map(b=>{ const l=(b.labels||[]).join(', '); return b.title+' | '+b.url+(l?(' | '+l):''); }).join('\n');
  const blob=new Blob([text],{type:'text/plain'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='my-bookmarks.txt';
  document.body.appendChild(a); a.click(); a.remove();
  showBanner('Exported your links to a file.');
};

