window.setSort=function(v){ sortMode=v; render(); };

// ---- Bulk actions ----
window.toggleSelectMode=function(){ selectMode=!selectMode; selected.clear(); bulkLabelOpen=false; bulkDeleteConfirm=false; render(); };
window.toggleSelect=function(id){ if(selected.has(id)) selected.delete(id); else selected.add(id); bulkDeleteConfirm=false; render(); };
window.bulkSelectAll=function(){ lastShown.forEach(id=>selected.add(id)); render(); };
window.bulkClear=function(){ selected.clear(); bulkLabelOpen=false; bulkDeleteConfirm=false; render(); };
window.bulkReadLater=function(){ selected.forEach(id=>{ const b=bookmarks.find(x=>x.id===id); if(b) b.toRead=true; }); showBanner('Flagged '+selected.size+' to read.'); render(); };
window.bulkLabelToggle=function(){ bulkLabelOpen=!bulkLabelOpen; bulkDeleteConfirm=false; render(); };
window.bulkApplyLabel=function(raw){
  const label=canonicalLabel(raw); if(!label) return;
  let n=0; selected.forEach(id=>{ const b=bookmarks.find(x=>x.id===id); if(b){ b.labels=b.labels||[]; if(!hasLabel(b,label)){ b.labels.push(label); n++; } } });
  bulkLabelOpen=false; showBanner('Added “'+label+'” to '+n+' link'+(n===1?'':'s')+'.'); render();
};
window.bulkApplyLabelInput=function(){ const el=document.getElementById('bulkLabelInput'); if(el && el.value.trim()) bulkApplyLabel(el.value); };
window.bulkDeleteAsk=function(){ bulkDeleteConfirm=true; bulkLabelOpen=false; render(); };
window.bulkDeleteDo=function(){
  const n=selected.size;
  for(let i=bookmarks.length-1;i>=0;i--){ if(selected.has(bookmarks[i].id)) bookmarks.splice(i,1); }
  selected.clear(); bulkDeleteConfirm=false; showBanner('Deleted '+n+' link'+(n===1?'':'s')+'.'); render();
};

function renderBulk(){
  const btn=document.getElementById('selBtn');
  if(btn){ btn.textContent = selectMode ? 'Cancel' : 'Select'; btn.classList.toggle('on', selectMode); }
  const bar=document.getElementById('bulkbar');
  if(!selectMode){ bar.innerHTML=''; return; }
  const n=selected.size;
  const labels=allLabels();
  const sub = bulkLabelOpen
    ? `<div class="sub">
         <div style="margin-bottom:6px;">Add a label to ${n} selected — tap an existing one or type a new one:</div>
         <input id="bulkLabelInput" placeholder="Label…" onkeydown="if(event.key==='Enter') bulkApplyLabelInput()" />
         <button onclick="bulkApplyLabelInput()" style="margin-left:6px;">Add</button>
         <div class="palette">${labels.map(l=>`<span class="addchip" onclick="bulkApplyLabel('${escapeHtml(l)}')">${escapeHtml(l)}</span>`).join('')||'<span style="color:#8a94a3;">No labels yet — type one above.</span>'}</div>
       </div>`
    : '';
  const confirm = bulkDeleteConfirm
    ? `<div class="sub">Delete ${n} link${n===1?'':'s'} for good, saved copies and all?
         <button class="danger" style="margin-left:8px;" onclick="bulkDeleteDo()">Yes, delete ${n}</button>
         <button onclick="bulkClear()">Cancel</button></div>`
    : '';
  bar.innerHTML =
    `<div class="inner">
      <b>${n} selected</b>
      <button class="ghost" onclick="bulkSelectAll()">Select all shown</button>
      <span class="spacer"></span>
      <button ${n?'':'disabled'} onclick="bulkLabelToggle()">Label…</button>
      <button ${n?'':'disabled'} onclick="bulkReadLater()">Read later</button>
      <button class="danger" ${n?'':'disabled'} onclick="bulkDeleteAsk()">Delete</button>
      <button class="ghost" onclick="toggleSelectMode()">Done</button>
      ${sub}${confirm}
    </div>`;
}

